// Normalize inputs from Manual / ExecuteWorkflow / Webhook triggers into one shape.
const src = $json || {};
const q = (src.query && typeof src.query === 'object') ? src.query : {};
const body = (src.body && typeof src.body === 'object') ? src.body : {};
const pick = (k, dflt) => {
  const v = src[k] ?? q[k] ?? body[k];
  return (v === undefined || v === null || v === '') ? dflt : String(v);
};
const clientName = pick('clientName', 'Acme GmbH');
const projectType = pick('projectType', 'Web application development');
const scopeNotes = pick('scopeNotes', 'Build a modern, responsive web application with user authentication, a dashboard, and reporting.');
const budget = pick('budget', '[PLACEHOLDER: budget not provided]');
return [{ json: { clientName, projectType, scopeNotes, budget } }];

const { clientName, projectType, scopeNotes, budget } = $json;
const system = `You are Vera, the client concierge for a solo software agency based in Berlin. You write all client-facing communication. Voice: warm, calm, professional, concrete. Plain language — never jargon, never hype. At most one exclamation mark per message. Every message ends with exactly one clear next step or question. Mirror the client's language (German or English) and formality; in German default to "Sie" unless the client used "du". Never invent prices, deadlines, scope, or commitments — if a fact is missing, insert a literal [PLACEHOLDER: what's needed] and flag it. Never apologize more than once. Sign off as the agency owner, not as an AI. Output only the message body unless asked otherwise.`;

const task = `Draft a professional project proposal for the client below. Write in clear English prose suitable for a polished PDF document.

Client: ${clientName}
Project type: ${projectType}
Scope notes: ${scopeNotes}
Budget: ${budget}

Produce EXACTLY these six sections, each prefixed with its heading on its own line in this exact format "## <Section Name>":
## Overview
## Scope & Deliverables
## Approach
## Timeline
## Investment
## Next Steps

Rules:
- Overview: 2-3 sentences framing the engagement and the value to ${clientName}.
- Scope & Deliverables: a bulleted list (use "- " prefixes) of concrete deliverables derived from the scope notes.
- Approach: 2-4 sentences on methodology / how you'll work.
- Timeline: describe phases and rough durations as bullet points (use "- " prefixes). Do not invent exact calendar dates.
- Investment: reference the budget. If budget is a placeholder, keep the literal [PLACEHOLDER: ...] text. Do not invent numbers.
- Next Steps: exactly one clear call to action.
Do not add any text before "## Overview" or after the Next Steps section.`;

return [{ json: { model: 'qwen3:8b', prompt: system + '\n\n' + task, clientName, projectType, scopeNotes, budget } }];

// Inputs: LLM response in $json.response. Original client vars from the Build Prompt node.
const raw = ($json.response || '').toString();
const vars = $('Build Prompt').first().json;
const clientName = vars.clientName || 'Client';
const budget = vars.budget || '';

// Strip any <think> blocks just in case.
let text = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Split the LLM output into the six sections by '## Heading'.
function sectionBody(name) {
  const re = new RegExp('##\\s*' + name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*([\\s\\S]*?)(?=\\n##\\s|$)', 'i');
  const m = text.match(re);
  return m ? m[1].trim() : '';
}

// Convert a chunk that may contain '- ' bullet lines into HTML (ul) or paragraphs.
function toHtml(chunk) {
  if (!chunk) return '<p class="muted">[PLACEHOLDER: content not generated]</p>';
  const lines = chunk.split(/\n+/).map(l => l.trim()).filter(Boolean);
  const bullets = lines.filter(l => /^[-*•]\s+/.test(l));
  if (bullets.length && bullets.length >= lines.length - 1) {
    const items = lines.map(l => '<li>' + esc(l.replace(/^[-*•]\s+/, '')) + '</li>').join('');
    return '<ul>' + items + '</ul>';
  }
  return lines.map(l => '<p>' + esc(l) + '</p>').join('');
}

const overview   = sectionBody('Overview');
const scope      = sectionBody('Scope & Deliverables') || sectionBody('Scope and Deliverables') || sectionBody('Scope of Work');
const approach   = sectionBody('Approach');
const timeline   = sectionBody('Timeline');
const investment = sectionBody('Investment');
const nextSteps  = sectionBody('Next Steps');

const dateStr = new Date().toLocaleDateString('en-GB', { year: 'numeric', month: 'long', day: 'numeric' });

const html = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  :root{
    --brand:#1F3A5F; --accent:#3E7CB1; --ink:#1A1A1A; --muted:#6B7280;
    --line:#E5E7EB; --bg-soft:#F7F9FC; --font:'Helvetica Neue',Arial,sans-serif;
  }
  @page{ size:A4; margin:18mm 16mm; }
  *{ box-sizing:border-box; -webkit-print-color-adjust:exact; print-color-adjust:exact; }
  body{ font-family:var(--font); color:var(--ink); font-size:11pt; line-height:1.5; margin:0; }
  h1{ color:var(--brand); font-size:22pt; margin:0 0 4px; }
  h2{ color:var(--brand); font-size:13pt; border-bottom:2px solid var(--accent);
      padding-bottom:4px; margin:24px 0 10px; }
  .muted{ color:var(--muted); } .right{ text-align:right; } .small{ font-size:9pt; }
  .brandbar{ height:6px; background:linear-gradient(90deg,var(--brand),var(--accent)); }
  ul{ margin:8px 0; padding-left:20px; } li{ margin:4px 0; }
  p{ margin:8px 0; }
</style>
</head>
<body>
<div class="brandbar"></div>
<div style="margin-top:60px;text-align:center">
  <h1 style="font-size:30pt;margin-top:30px">Project Proposal</h1>
  <p class="muted">Prepared for ${esc(clientName)} · ${esc(dateStr)}</p>
</div>
<div style="page-break-after:always"></div>
<h2>1. Overview</h2>
${toHtml(overview)}
<h2>2. Scope &amp; Deliverables</h2>
${toHtml(scope)}
<h2>3. Approach</h2>
${toHtml(approach)}
<h2>4. Timeline</h2>
${toHtml(timeline)}
<h2>5. Investment</h2>
${toHtml(investment)}
<h2>6. Next Steps</h2>
${toHtml(nextSteps)}
<div class="small muted" style="margin-top:40px">Berlin Software Agency · hello@agency.example · agency.example</div>
</body>
</html>`;

return [{ json: { html, clientName } }];
